// ❌ OLD: The borrow checker REJECTS mutating through a shared
// reference at compile time:
//   let mut v = Vec::new();
//   let shared = &v;
//   v.push(1); // error[E0502]: cannot borrow `v` as mutable because
//             // it is also borrowed as immutable
// This is the safe-Rust rule: no aliasing + mutation. But some
// legitimate patterns (a cache, a graph, a callback that mutates
// captured state) NEED mutation behind shared references — which is
// what the interior-mutability types provide.
fn main() {
    let mut v = vec![1];
    let _shared = &v;
    // v.push(2); // ❌ OLD: compile error (E0502)
}

use std::cell::RefCell;

// ✅ NEW: RefCell moves the aliasing check from compile time to
// runtime. You can hold shared references to the RefCell while
// borrowing its contents mutably through borrow_mut().
fn main() {
    let cell = RefCell::new(vec![1]);

    // ✅ NEW: exclusive borrow at runtime — the borrow flag is checked
    cell.borrow_mut().push(2);

    // Shared borrows are fine (multiple readers):
    let a = cell.borrow();
    let b = cell.borrow(); // ✅ NEW: two shared borrows OK
    drop(a);
    drop(b);

    // ⚠️ Violation panics at runtime:
    // let m = cell.borrow_mut();
    // let n = cell.borrow_mut(); // panic: already mutably borrowed
}

// Cell for Copy types, RefCell for single-threaded, Mutex/RwLock for
// sharing across threads.
